def _unit_for(h):
    h=str(h)
    if "万" in h or h in ("销售额","贡献","固定费用","一次性","阶段费用","寄样货值","经营结果","当期现金","14 个月结果","2027 年末累计现金","资金峰值","2028 经营","2028 年末累计现金","已发生净支出","在途和未付货款","代运营合同余款","清货期间费用","库存清货净回收","完整结算","增量一次性支出","2027 年多带来的贡献","2028 年多带来的贡献","14 个月结果差","资金峰值差","获客费用"): return " 万美元"
    if h in ("销量","2027 销量","交付台数","期初","到货","寄样送评样品备件","销售","可再售退货","期末","缺货未交","2027 年销量"): return " 台"
    if h in ("均价","每台贡献","每台","每台获客成本","交付后贡献","扣获客后贡献","原价","到仓成本","亚马逊首发期","亚马逊稳定期","零售批发 55%","场所 65%","全国独立站","纽约独立站","限量版纽约"): return " 美元"
    return ""
def _add_unit(cell,unit):
    s=str(cell)
    if not unit or not _re.fullmatch(r"<b>?[−\-+]?[\d,]+(\.\d+)?</b>?|[−\-+]?[\d,]+(\.\d+)?",s.strip()): return s
    if s.strip().endswith("</b>"): return s.replace("</b>",unit+"</b>")
    return s+unit
def table(head,rows,cls=""):
    units=[_unit_for(h) for h in head]
    h="<table class='%s'><thead><tr>"%cls+"".join(f"<th>{esc(c)}</th>" for c in head)+"</tr></thead><tbody>"
    for r in rows: h+="<tr>"+"".join(f"<td>{_add_unit(c,units[i] if i<len(units) else '')}</td>" for i,c in enumerate(r))+"</tr>"
    return h+"</tbody></table>"
def tw(head,rows,cls=""): return "<div class='tw'>"+table(head,rows,cls)+"</div>"
